 if(type==='products')f=nameField()+field('sku','Штрихкод / артикул',v.sku||'')+field('brand','Бренд',v.brand||'')+select('category','Тип продукта',state.productTypes.map(c=>({id:c.name,name:c.name})),v.category||'Материалы')+select('unit','Единица измерения',state.units.map(c=>({id:c.name,name:c.name})),v.unit||'шт')+field('price','Цена продажи, ₾',v.price||0,'number','min="0" step="0.01"')+field('lossFactor','Коэффициент стоимости с учётом потерь',v.lossFactor||1,'number','min=1 max=10 step=0.01')+check('active','Активный товар',v.active!==false)+field('threshold','Порог низкого остатка',v.threshold||0,'number','min="0" step="0.001"');
 if(type==='schedule'){v=schedule(state,id,day);f=field('date','Дата',day,'date','required')+field('start','Начало',v.start,'time','required')+field('end','Конец',v.end,'time','required')+field('breakStart','Начало перерыва',v.breakStart,'time')+field('breakEnd','Конец перерыва',v.breakEnd,'time')+check('off','Выходной',v.off);}
 if(type==='payment'){const a=state.appointments.find(a=>a.id===id);f=`<p>${esc(a.name)} · ${esc(a.service)} · ${money(a.price)}</p>`+select('method','Способ оплаты',[{id:'cash',name:'Наличные'},{id:'card',name:'Карта / безналичные'}])+select('promotionId','Применить акцию',state.promotions.filter(p=>p.active&&today()>=p.start&&today()<=p.end).map(p=>({...p,name:p.name+' −'+p.discount+'%'})),'',true)+notice('Это внутренний учёт оплаты. Деньги с карты не списываются.');}
 if(type==='advances')f=select('employeeId','Мастер',state.employees)+field('date','Дата',today(),'date','required')+field('amount','Выдано, ₾','','number','min="0.01" step="0.01" required')+field('note','Примечание');
 if(type==='expenses')f=nameField()+field('date','Дата',today(),'date','required')+field('amount','Сумма, ₾','','number','min="0.01" step="0.01" required');
 if(type==='cash')f=select('kind','Операция',[{id:'in',name:'Внести'},{id:'out',name:'Изъять'}])+field('amount','Сумма, ₾','','number','min="0.01" step="0.01" required')+field('reason','Основание','','text','required');
