 if(type==='shift-close')f=notice('Ожидаемая наличность: '+money(cashBalance(state)))+field('actual','Фактическая наличность, ₾',cashBalance(state),'number','min="0" step="0.01" required');
 if(type==='suppliers')f=nameField()+field('phone','Телефон',v.phone||'')+field('note','Примечание',v.note||'');
 if(type==='suppliers')f+=field('email','Email',v.email||'','email')+field('contact','Контактное лицо',v.contact||'')+field('brands','Бренды',v.brands||'');
