 if(type==='workplaces')f=nameField()+field('kind','Тип',v.kind||'Кресло')+field('x','Положение по горизонтали, %',v.x||10,'number','min="0" max="100"')+field('y','Положение по вертикали, %',v.y||10,'number','min="0" max="100"');
 if(type==='workplaces')f+=field('zone','Зона',v.zone||'Основной зал')+select('status','Статус',['Свободно','Занято','Ждёт оплаты','Черновик','Забронировано','Уборка','Не обслуживается','Зарезервировано'].map(name=>({id:name,name})),v.status||'Свободно');
 if(type==='promotions')f=nameField()+field('discount','Скидка, %',v.discount||10,'number','min="0" max="100"')+field('start','Начало',v.start||today(),'date','required')+field('end','Окончание',v.end||addDays(today(),30),'date','required')+check('active','Активна',v.active!==false);
 if(type==='purchase')f=select('productId','Товар',state.products)+select('warehouseId','Склад',state.warehouses,'main')+select('supplierId','Поставщик',state.suppliers,'',true)+field('date','Дата',today(),'date','required')+field('qty','Количество','','number','min="0.001" step="0.001" required')+field('cost','Цена закупки за единицу, ₾','','number','min="0" step="0.01" required');
