function showTour(i){const steps=[['Панель','Здесь — выручка, кассовая смена и визиты.','dashboard'],['Календарь','Мастера по колонкам. Нажмите на визит для оплаты или отмены.','calendar'],['Графики','Настройте выходные и перерывы перед открытием онлайн-записи.','schedule'],['Услуги и материалы','Привяжите мастеров и расход материалов к услугам.','services'],['Клиенты','Откройте карточку клиента для истории и заметок.','clients'],['Настройки','Задайте данные салона и параметры записи.','settings']];const [h,t,target]=steps[i];go(target);modal.innerHTML=`<div class="modal-heading"><h2>${h}</h2><button data-close>×</button></div><p>${t}</p><p class="muted">Шаг ${i+1} из ${steps.length}</p>${btn(i===steps.length-1?'Готово':'Далее','data-next','primary')}`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('[data-next]').onclick=()=>{modal.close();if(i<steps.length-1)showTour(i+1);};modal.showModal();}
function exportCSV(type){const rows=type==='stock'?[['name','brand','category','sku','unit','quantity','threshold','price'],...state.products.map(p=>[p.name,p.brand,p.category,p.sku,p.unit,stock(state,p.id),p.threshold,p.price])]:type==='clients'?[['name','phone','tags'],...state.clients.map(c=>[c.name,c.phone,c.tags])]:[['date','client','service','status','amount','method'],...receipts(state).map(a=>[a.paidDate||a.date,a.name,a.service,a.status,a.amount??a.price,a.method||''])];const text='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='SayYes-'+type+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function parseCSV(text){const rows=[[]];let value='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){rows.at(-1).push(value);value='';}else if(c==='\n'&&!quoted){rows.at(-1).push(value.replace(/\r$/,''));rows.push([]);value='';}else value+=c;}if(quoted)throw Error('Незакрытая кавычка CSV');rows.at(-1).push(value.replace(/\r$/,''));return rows;}
