 if(active==='По местам')content=table(['Место','Зона','Чеков','Выручка','Средний чек'],state.workplaces.map(w=>{const a=r.filter(a=>a.workplaceId===w.id);return [esc(w.name),esc(w.zone),a.length,money(sum(a,'amount')),money(a.length?sum(a,'amount')/a.length:0)];}));
