 if(page==='supplier-orders')return panel('Заказы поставщикам',table(['Дата','Поставщик','Состав','Статус'],state.supplierOrders.slice().reverse().map(o=>[o.date,nameOf('suppliers',o.supplierId),o.lines.map(l=>nameOf('products',l.productId)+' × '+l.qty).join('<br>'),esc(o.status)])),add('supplier-order','Заказ')+btn('CSV','data-table-export'))+notice('Заказы сохраняются как черновики и не отправляются поставщикам. Поступление оформляется отдельной закупкой.');
