function openPhaseTwoForm(type,id=''){
 if(!['schedule-pattern','expense-template','apply-expense-template','supplier-order'].includes(type))return false;
 let f='',heading='';
 if(type==='schedule-pattern'){heading='Повторяющийся график';f=select('employeeId','Сотрудник',state.employees,employee)+field('from','С даты',day,'date','required')+field('to','По дату',addDays(day,30),'date','required')+field('start','Начало','10:00','time','required')+field('end','Окончание','20:00','time','required')+field('breakStart','Перерыв с','','time')+field('breakEnd','Перерыв до','','time')+check('off','Выходные дни',false)+['Вс','Пн','Вт','Ср','Чт','Пт','Сб'].map((n,i)=>check('weekday:'+i,n,i>0&&i<6)).join('');}
 if(type==='expense-template'){const t=state.expenseTemplates.find(t=>t.id===id);heading='Шаблон базовых расходов';f=field('name','Название',t?.name||'','text','required')+check('isDefault','По умолчанию для новых услуг',t?.isDefault)+`<label>Расходы: одна строка «Название; сумма»<textarea name="rows" required rows="6">${esc(t?.lines.map(l=>l.name+'; '+l.amount).join('\n')||'')}</textarea></label>`;}
 if(type==='apply-expense-template'){heading='Применить шаблон к услугам';f=notice('Базовые затраты выбранных услуг будут заменены суммой шаблона.')+state.services.map(v=>check('service:'+v.id,esc(v.name),false)).join('');}
 if(type==='supplier-order'){heading='Черновик заказа';f=select('supplierId','Поставщик',state.suppliers)+field('note','Примечание')+state.products.filter(p=>p.active!==false).map(p=>extNumber('product:'+p.id,esc(p.name)+' · остаток '+stock(state,p.id),0)).join('');}
 modal.innerHTML=`<div class="modal-heading"><h2>${heading}</h2>${btn('×','type="button" data-close')}</div><form>${f}<p class="form-error" role="alert"></p><button class="primary" type="submit">Сохранить</button></form>`;modal.querySelector('[data-close]').onclick=()=>modal.close();
 const form=modal.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const b=Object.fromEntries(new FormData(form));form.querySelectorAll('[type=checkbox]').forEach(el=>b[el.name]=el.checked);if(id)b.id=id;
 if(type==='schedule-pattern')b.weekdays=Array.from({length:7},(_,i)=>i).filter(i=>b['weekday:'+i]);
 if(type==='expense-template')b.lines=b.rows.split('\n').filter(l=>l.trim()).map(l=>{const split=l.lastIndexOf(';');if(split<0)throw Error('Формат строки: название; сумма');return {name:l.slice(0,split),amount:l.slice(split+1).trim().replace(',','.')};});
 if(type==='apply-expense-template'){b.templateId=id;b.serviceIds=state.services.filter(v=>b['service:'+v.id]).map(v=>v.id);}
 if(type==='supplier-order')b.lines=state.products.filter(p=>Number(b['product:'+p.id])>0).map(p=>({productId:p.id,qty:Number(b['product:'+p.id])}));
 await post(type,b);modal.close();toast('Сохранено');}catch(err){form.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;}};modal.showModal();return true;
}
function bindPhaseTwo(){
 document.querySelector('[name=freeService]')?.addEventListener('change',e=>{freeService=e.target.value;render();});
 document.querySelector('[name=freeDays]')?.addEventListener('change',e=>{freeDays=Number(e.target.value);render();});
 document.querySelector('[data-share-slots]')?.addEventListener('click',()=>{const rows=collectFreeSlots();const text=state.settings.name+' — свободное время\n'+rows.map(r=>r.date+' · '+r.employee+' · '+r.times.join(', ')).join('\n')+'\nЗапись: '+bookingLink();modal.innerHTML='<h2>Текст для публикации</h2><textarea rows="15" style="width:100%" readonly>'+esc(text)+'</textarea>'+btn('Закрыть','data-close');modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();modal.querySelector('textarea').select();});

 document.querySelector('[name=floorZone]')?.addEventListener('change',e=>{floorZone=e.target.value;render();});
 document.querySelectorAll('[data-floor-item]').forEach(el=>{let start=null;el.onpointerdown=e=>{start={x:e.clientX,y:e.clientY};el.setPointerCapture(e.pointerId);};el.onpointermove=e=>{if(!start)return;const rect=el.parentElement.getBoundingClientRect();el.style.left=Math.max(0,Math.min(85,(e.clientX-rect.left)/rect.width*100))+'%';el.style.top=Math.max(0,Math.min(85,(e.clientY-rect.top)/rect.height*100))+'%';};el.onpointerup=async()=>{if(!start)return;start=null;const w=state.workplaces.find(w=>w.id===el.dataset.floorItem);try{await post('workplaces',{...w,x:parseFloat(el.style.left),y:parseFloat(el.style.top)});}catch(err){toast(err.message);render();}};el.onpointercancel=()=>{start=null;render();};});
 document.querySelectorAll('[data-archive-product]').forEach(b=>b.onclick=async()=>{try{await post('archive-product',{id:b.dataset.archiveProduct,archived:b.dataset.archived==='true'});}catch(e){toast(e.message);}});
}

function bookingLink(key='',value=''){const preview=location.pathname.endsWith('.html');const base=location.origin+ (preview?location.pathname:'/book');return base+(key?'?'+key+'='+encodeURIComponent(value):'');}
function collectFreeSlots(){const serviceId=freeService||state.services.find(s=>s.active)?.id;if(!serviceId)return [];return Array.from({length:freeDays},(_,i)=>addDays(day,i)).flatMap(date=>state.employees.filter(e=>e.active&&(!employee||e.id===employee)).map(e=>({date,employee:e.name,times:slots(state,e.id,serviceId,date,true)}))).filter(r=>r.times.length);}
function freeSlotsPage(){const rows=collectFreeSlots();return panel('Свободные окна для публикации',table(['Дата','Мастер','Свободное время'],rows.map(r=>[r.date,esc(r.employee),r.times.join(' · ')])),dateControls()+select('freeService','Услуга',state.services.filter(s=>s.active),freeService)+select('freeDays','Период',[{id:'7',name:'7 дней'},{id:'14',name:'14 дней'}],String(freeDays))+btn('Поделиться','data-share-slots'))+notice('Слоты учитывают длительность выбранной услуги, графики, визиты и временные брони. Публикация не удерживает время: доступность проверяется повторно при записи.');}
function managementView(){const a=managedBooking;const url=location.href.split('?')[0]+'?manage='+encodeURIComponent(bookingManageToken);return panel('Ваша запись',a?`<div class="padded"><h3>${esc(a.service)}</h3><p>${esc(a.date)} · ${esc(a.time)}</p><p>${a.status==='pending'?'Ожидает подтверждения салоном':a.status==='cancelled'?'Запись отменена':a.status==='paid'?'Визит оплачен':a.status==='refunded'?'Возврат оформлен':'Запись подтверждена'}</p><p>Сохраните персональную ссылку для управления записью:</p><input readonly value="${esc(url)}" aria-label="Ссылка управления">${a.allowCancel&&['pending','booked'].includes(a.status)?btn('Отменить запись','data-public-cancel'):''}${btn('Новая запись','data-new-public')}</div>`:notice('Загружаем запись…'));}
async function fetchManagedBooking(){const r=await fetch('/api/manage-booking',{headers:{'X-Booking-Token':bookingManageToken}});const data=await r.json();if(!r.ok)throw Error(data.error);managedBooking=data;if(state)render();}
function bindManagement(){document.querySelector('[data-new-public]')?.addEventListener('click',()=>{bookingManageToken='';managedBooking=null;history.replaceState({},'',location.pathname);load().catch(e=>toast(e.message));});document.querySelector('[data-public-cancel]')?.addEventListener('click',async()=>{if(!confirm('Отменить вашу запись?'))return;try{await post('cancel-booking',{token:bookingManageToken});await fetchManagedBooking();}catch(err){toast(err.message);}});}
const managementParam=new URLSearchParams(location.search).get('manage');if(promoParam)page='book';if(managementParam){page='book';bookingManageToken=managementParam;fetchManagedBooking().catch(e=>toast(e.message));}

// Task-oriented navigation. Existing routes and data remain available inside each workspace.
const workspaces=[
 {id:'dashboard',name:'Сегодня',icon:'◫',hint:'Визиты, смена и быстрые действия',pages:['dashboard','receipts','cash','shifts','terminal']},
 {id:'salon',name:'Салон',icon:'✂',hint:'Записи, клиенты и услуги',pages:['salon','calendar','clients','services','loyalty','promotions','slots','workplaces','floor','recipes']},
 {id:'bar',name:'Бар',icon:'☕',hint:'Товары, напитки и продажа',pages:['bar']},
 {id:'warehouse',name:'Склад',icon:'▧',hint:'Остатки, поступления и списания',pages:['warehouse','stock','products','purchases','transfers','supplier-orders']},
 {id:'team',name:'Команда',icon:'♧',hint:'Сотрудники, графики и выплаты',pages:['team','employees','schedule','assignments','payroll','advances','master']},
 {id:'business',name:'Бизнес',icon:'↗',hint:'Результаты и расходы',pages:['business','analytics','recommendations','promo-analytics']},
 {id:'setup',name:'Настройки',icon:'⚙',hint:'Параметры салона и справочники',pages:['setup','settings','booking-settings','loyalty-settings','payment-settings','messages','expense-templates','audit','import']}
];
const pageNames={dashboard:'Сегодня',salon:'Салон',bar:'Бар',warehouse:'Склад',team:'Команда',business:'Бизнес',setup:'Настройки',employees:'Сотрудники',stock:'Остатки и учёт',recipes:'Материалы услуг',shifts:'Кассовые смены',assignments:'Назначения на места',settings:'Профиль салона'};
let barCategory='',barQuery='';
const currentWorkspace=()=>workspaces.find(w=>w.pages.includes(page))||workspaces[0];
function workspaceTabs(){const w=currentWorkspace();if(w.pages.length<2)return '';const links=w.pages.map(id=>btn(esc(title(id)),`data-page="${id}" ${page===id?'aria-current="page"':''}`,page===id?'primary':'secondary'));return `<div class="workspace-tabs" aria-label="Разделы ${w.name}">${links.slice(0,4).join('')}${links.length>4?`<details class="more-pages"><summary>Ещё ${links.slice(4).some((_,i)=>w.pages[i+4]===page)?'· '+esc(title(page)):''}</summary><div>${links.slice(4).join('')}</div></details>`:''}</div>`;}
function workspaceIcon(key){const paths={
 '✂':'M6 6m-3 0a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M6 18m-3 0a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M8 8l13 13 M8 16L21 3',
 '☕':'M4 8h12v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8 M16 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M11 2v3',
 '↗':'M4 17l6-6 4 4 6-11 M14 4h6v6',
 '＋':'M12 4v16 M4 12h16',
 '♡':'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 15 7-6 12-11 8-15Z',
 '♧':'M9 4a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M19 15a5 5 0 0 1 3 6',
 '▧':'M3 7l9-5 9 5v10l-9 5-9-5V7 M3 7l9 5 9-5 M12 12v10',
 '◷':'M12 2a10 10 0 1 0 0 20a10 10 0 1 0 0-20 M12 6v6l4 3',
 '₾':'M3 6h18v14H3V6 M3 10h18 M15 14h6 M6 3h12',
 '⚙':'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',
 '◫':'M3 3h18v18H3V3 M9 3v18 M9 10h12',
 '▦':'M3 5h18v16H3V5 M3 10h18 M7 2v6 M17 2v6 M7 14h2 M13 14h2 M7 18h2',
 '▱':'M4 3h16v9H4V3 M2 12h20v5H2v-5 M5 17v5 M19 17v5'
 };return `<svg class="workspace-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[key]||'M4 3h16v18H4V3 M8 8h8 M8 12h8 M8 16h5'}"/></svg>`;}
const actionCard=(icon,label,detail,attrs,accent='')=>`<button class="action-card ${accent}" ${attrs}><span class="action-icon">${workspaceIcon(icon)}</span><b>${label}</b><small>${detail}</small><span class="card-arrow">${workspaceIcon('↗')}</span></button>`;
function workspaceHome(){
 if(page==='dashboard'){
  const visits=state.appointments.filter(a=>a.date===today()&&!['cancelled','refunded'].includes(a.status)).sort((a,b)=>a.start-b.start),pending=state.appointments.filter(a=>a.status==='pending'),low=state.products.filter(p=>p.active!==false&&stock(state,p.id)<=p.threshold),sh=shift();
  return `<section class="day-intro"><div><span class="section-kicker">${esc(new Date().toLocaleDateString('ru-RU',{timeZone:'Asia/Tbilisi',weekday:'long',day:'numeric',month:'long'}))}</span><h2>Всё для хорошего рабочего дня.</h2><p>Запишите клиента, оформите продажу или проверьте смену.</p></div><div class="shift-status"><span class="status-dot"></span>${sh?'Смена открыта':'Смена ещё не открыта'}<strong>${sh?money(cashBalance(state)):'Начните рабочий день'}</strong>${sh?btn('Открыть кассу','data-page="cash"'):btn('Открыть смену','data-form="shift-open"','primary')}</div></section>
  <div class="quick-actions">${actionCard('＋','Записать клиента','Выбрать услугу, мастера и время','data-form="appointments"','accent-salon')}${actionCard('₾','Продать и принять оплату','Услуги и товары в одном чеке','data-form="sale"')}${actionCard('♡','Добавить клиента','Контакты, заметки и история','data-form="clients"')}</div>
  <div class="workspace-launchers">${actionCard('✂','Салон','Календарь мастеров, клиенты и услуги','data-page="salon"','accent-salon')}${actionCard('☕','Бар','Каталог товаров и быстрые продажи','data-page="bar"','accent-bar')}</div>
  <div class="day-columns"><section>${panel('Визиты сегодня',visits.length?receiptTable(visits):`<div class="friendly-empty"><span>▦</span><h3>Сегодня пока нет записей</h3><p>Создайте первый визит или откройте календарь на другую дату.</p>${add('appointments','Записать клиента')}</div>`,btn('Весь календарь','data-page="calendar"'))}</section><section>${panel('Требует внимания',`<div class="attention-list">${pending.length?`<button data-page="receipts"><b>${pending.length} записей ждут подтверждения</b><small>Проверьте новые онлайн-записи →</small></button>`:''}${low.length?`<button data-page="stock"><b>${low.length} товаров пора пополнить</b><small>Проверить остатки →</small></button>`:''}${!pending.length&&!low.length?'<div class="quiet-state"><b>Всё спокойно</b><p>Здесь появятся записи на подтверждение и товары с низким остатком.</p></div>':''}</div>`)}${panel('Быстрый доступ',`<div class="shortcut-list">${btn('Свободные окна →','data-page="slots"')}${btn('Принять товар →','data-form="purchase-document"')}${btn('Результаты бизнеса →','data-page="business"')}</div>`)}</section></div>`;
 }
 if(page==='salon')return `<div class="workspace-intro"><p>Работа с клиентом — от первой записи до следующего визита.</p>${btn('Новая запись','data-form="appointments"','primary')}</div><div class="hub-grid">${actionCard('▦','Календарь мастеров','День, неделя и месяц','data-page="calendar"','accent-salon')}${actionCard('♡','Клиенты','Контакты, история визитов и заметки','data-page="clients"')}${actionCard('✂','Услуги и цены','Длительность, мастера и материалы','data-page="services"')}${actionCard('◷','Свободные окна','Подобрать время и подготовить публикацию','data-page="slots"')}${actionCard('◇','Лояльность и акции','Бонусные счета и специальные предложения','data-page="loyalty"')}${actionCard('▱','План зала','Рабочие места и их расположение','data-page="floor"')}</div>`;
 if(page==='bar'){
  const products=state.products.filter(p=>p.active!==false),categories=[...new Set(products.map(p=>p.category||'Без категории'))],list=products.filter(p=>(!barCategory||p.category===barCategory)&&(p.name+' '+p.brand).toLowerCase().includes(barQuery.toLowerCase()));
  return `<div class="workspace-intro"><div><p>Выберите товар, затем укажите количество и способ оплаты.</p><small>Каталог общий со складом. Категории помогут найти напитки и товары бара.</small></div>${add('sale','Новый чек')}</div><div class="bar-tools"><input id="bar-search" type="search" placeholder="Найти напиток или товар" aria-label="Поиск товара" value="${esc(barQuery)}"><select id="bar-category" aria-label="Категория"><option value="">Все категории</option>${opts(categories.map(name=>({id:name,name})),barCategory)}</select></div><div class="product-grid">${list.map(p=>`<button class="product-tile" data-bar-product="${p.id}"><span class="product-category">${esc(p.category)}</span><h3>${esc(p.name)}</h3><small>${esc(p.brand)||'Товар'} · ${stock(state,p.id)} ${esc(p.unit)} на складе</small><strong>${money(p.price)}</strong><span class="product-buy">Добавить в чек ＋</span></button>`).join('')}</div>${!list.length?panel('Каталог бара',`<div class="friendly-empty"><span>☕</span><h3>${products.length?'Ничего не найдено':'Добавьте первые товары'}</h3><p>${products.length?'Измените поиск или категорию.':'Создайте товары и примите их на склад. После этого можно оформлять продажи.'}</p>${add('products','Добавить товар')}${btn('Принять товар','data-form="purchase-document"')}</div>`):''}<div class="inline-links">${btn('Чеки и оплаты','data-page="receipts"')}${btn('Остатки товаров','data-page="products"')}${btn('Кассовая смена','data-page="cash"')}</div>`;
 }
 const hubs={warehouse:[['stock','▧','Остатки и учёт','Товары, партии и движение запасов'],['purchases','↙','Закупки','Поступления и накладные'],['products','□','Товары','Карточки, цены и архив'],['transfers','⇄','Перемещения','Передача между складами'],['supplier-orders','▤','Заказы поставщикам','Подготовить список для закупки']],team:[['employees','♧','Сотрудники','Карточки мастеров и ставки'],['schedule','▦','Графики','Рабочие часы, перерывы и выходные'],['assignments','▱','Назначения на места','Кто работает на каком месте'],['payroll','₾','Зарплата','Начисления, остатки и выплаты'],['advances','↗','Авансы','История выданных авансов']],business:[['analytics','↗','Результаты бизнеса','Выручка, расходы и прибыль'],['recommendations','✧','Требует внимания','Остатки и незавершённые визиты'],['promo-analytics','◇','Результаты акций','Оплаты и предоставленные скидки']],setup:[['settings','⚙','Профиль салона','Название и контакты'],['booking-settings','◷','Онлайн-запись','Подтверждение, бронь и отмены'],['payment-settings','₾','Оплата','Способы оплаты, банки и комиссии'],['loyalty-settings','♡','Бонусная программа','Начисление, списание и семейные счета'],['expense-templates','▤','Базовые расходы','Шаблоны затрат на услуги'],['messages','✉','Уведомления','Шаблоны и очередь сообщений'],['audit','≡','Журнал событий','История действий в системе'],['import','⇧','Перенос данных','Импорт и экспорт клиентов']]};
 if(hubs[page])return `${page==='business'?stats([['ВЫРУЧКА ЗА МЕСЯЦ',money(sum(receiptsInMonth(),'amount'))],['ОПЛАЧЕННЫХ ЧЕКОВ',receiptsInMonth().length],['РАСХОДЫ ЗА МЕСЯЦ',money(sum(state.expenses.filter(e=>e.date.startsWith(period)),'amount'))],['ПЕРИОД',period]]):''}<div class="hub-grid">${hubs[page].map(([id,icon,n,d])=>actionCard(icon,n,d,`data-page="${id}"`)).join('')}</div>`;
 return null;
}
function bindWorkspace(){
 document.querySelector('#workspace-search')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase(),target=document.querySelector('#workspace-results');const matches=q?[...workspaces.map(w=>({id:w.id,name:w.name})),...nav.map(([id,,name])=>({id,name:pageNames[id]||name}))].filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i&&x.name.toLowerCase().includes(q)):[];target.hidden=!q;target.innerHTML=matches.length?matches.map(x=>btn(esc(x.name),`data-search-page="${x.id}"`)).join(''):'<p>Раздел не найден</p>';target.querySelectorAll('[data-search-page]').forEach(b=>b.onclick=()=>go(b.dataset.searchPage));});
 document.querySelector('#bar-category')?.addEventListener('change',e=>{barCategory=e.target.value;render();});document.querySelector('#bar-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;barQuery=e.target.value;render();const input=document.querySelector('#bar-search');input.focus();input.setSelectionRange(pos,pos);});
 document.querySelectorAll('[data-bar-product]').forEach(b=>b.onclick=()=>{openForm('sale');const item=modal.querySelector('[name=item]');item.value='product:'+b.dataset.barProduct;item.dispatchEvent(new Event('change',{bubbles:true}));});
}

load().catch(e=>{app.innerHTML=`<p class="notice">Не удалось загрузить SayYes: ${esc(e.message)}. Обновите страницу или откройте самостоятельный предпросмотр.</p>`;});
